  "contradictory_card_ids": ["C09", "C31", "C36", "C75"],
  "prediction_basis_card_ids": ["C18", "C24", "C10", "C21", "C22", "C33", "C08", "C23", "C73", "C79"],
  "claims": [
    {
      "claim": "Direct L1 human F measurements for structurally related polar polycyclic lactones are at or above 20%: DHA 45% (95% CI 34-56), etoposide 38-52% and 48±18%, 9-AC 27-49%, and hydrocortisone 56-96%.",
      "card_ids": ["C18", "C24", "C02", "C22", "C25", "C28", "C33", "C10", "C21", "C08", "C23"]
    },
    {
      "claim": "L5 bilobalide, the closest terpene-trilactone analog to the query, shows moderate Caco-2 absorptive Papp (4.96±0.12 ×10^-6 cm/s) and no significant efflux (secretory 5.31±0.02 ×10^-6 cm/s), with increased transport at pH 5.0; this supports intestinal absorption rather than gut-wall loss.",
      "card_ids": ["C73", "C79", "C77"]
    },
    {
      "claim": "The low-F L1 records are not transferable to the query: omadacycline 0.6% was measured 4 h after a high-fat meal, CGP 43371 9% is a different chemotype, and moxidectin 10.6% is an alpaca relative-F value versus SC.",
      "card_ids": ["C09", "C31", "C36"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20% for the query; the 9-NC Caco-2 Papp below 1e-5 cm/s (C75) is less structurally relevant, and the 9-AC context shows oral F 27-49% despite similar solubility/permeability limitations.",
      "card_ids": ["C75", "C10", "C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C73", "C77", "C79", "C75", "C71", "C82"]
    }
  ],
  "evidence_gaps": [
    "No direct human or animal absolute oral bioavailability measurement for the query molecule (ginkgolide-type terpene trilactone).",
    "No matched oral versus IV exposure data for the query.",
    "No ginkgolide-specific Caco-2 permeability, efflux, or intestinal metabolism data; only bilobalide as a close structural analog.",
    "First-pass metabolism, lactone stability, and transporter status of the query are unknown.",
    "Query logD -1.37 and TPSA 148.8 remain unresolved permeability concerns."
  ],
  "decision_summary": "L5 adds bilobalide Caco-2 data showing moderate permeability and no significant efflux in a close terpene-trilactone analog, supporting absorption; combined with direct human F values for related polar polycyclic lactones (DHA 45%, etoposide 38-52%, 9-AC 27-49%, hydrocortisone 56-96%) and no transferable affirmative low-F evidence, F >= 20% remains better supported. Prediction high with low confidence."
}

